function featurePage(type){const config={academy:{eyebrow:'TurfMate Academy',title:'Build your game.<br>One skill at a time.',copy:'Practical football learning for every level — from first touch to match-day confidence.',cards:[['⚽','Ball mastery','Dribbling, first touch and close control.'],['↗','Passing & shooting','Technique, decision-making and finishing.'],['✦','Football fitness','Strength, speed, mobility and recovery.']]},community:{eyebrow:'TurfMate Community',title:'Find your people.<br>Make the match happen.',copy:'Build a squad, find players nearby and organise friendly games with less back-and-forth.',cards:[['♟','Create a team','Give your squad a name, identity and home turf.'],['⌖','Find players','Connect with players looking for a game.'],['✉','Invite your friends','Bring your teammates together in one place.']]},tournaments:{eyebrow:'TurfMate Tournaments',title:'A little competition<br>makes it better.',copy:'Discover local competitions, follow fixtures and bring your team into the game.',cards:[['🏆','Discover events','Find upcoming local football tournaments.'],['☷','Fixtures & results','Follow match schedules and results.'],['⚑','Team registration','A simpler route from interest to entry.']]},store:{eyebrow:'TurfMate Store',title:'Gear up for<br>your next game.',copy:'A curated marketplace for boots, jerseys, balls and training essentials — planned after core booking.',cards:[['⚽','Football essentials','Match balls, cones, bibs and accessories.'],['✦','Boots & apparel','Boots, jerseys, socks and match-day gear.'],['▣','Team kits','Custom jerseys and squad merchandise.']]}}[type];return `<section class="page-hero"><div class="container"><div class="eyebrow">${config.eyebrow}</div><h1>${config.title}</h1><p>${config.copy}</p><span class="coming">Planned feature · booking comes first</span></div></section><section class="section"><div class="container"><div class="feature-grid">${config.cards.map(c=>`<article class="feature-card"><div class="feature-icon">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}</p><span class="coming">Coming in a later phase</span></article>`).join('')}</div></div></section>`}

